create extension if not exists "pgcrypto";
create type gender_label as enum ('Woman','Man','Non-binary','Prefer not to say');
create type like_kind as enum ('interested','garba_vibe');
create type report_reason as enum ('harassment','fake_profile','inappropriate_content','spam','other');
create table profiles (id uuid primary key references auth.users(id) on delete cascade, first_name text not null check (char_length(first_name) between 1 and 40), age integer not null check (age >= 18), gender gender_label not null, branch text not null, year integer not null check (year between 1 and 4), bio text not null default '' check (char_length(bio) <= 200), experience text not null, styles text[] not null default '{}', looking_for text[] not null default '{}', available_nights smallint[] not null default '{}', interests text[] not null default '{}', partner_preference text not null default 'Everyone', photo_path text, is_hidden boolean not null default false, is_suspended boolean not null default false, is_banned boolean not null default false, onboarding_complete boolean not null default false, is_demo boolean not null default false, last_active_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table likes (id uuid primary key default gen_random_uuid(), from_user uuid not null references profiles(id) on delete cascade, to_user uuid not null references profiles(id) on delete cascade, kind like_kind not null, created_at timestamptz not null default now(), unique(from_user,to_user), check(from_user <> to_user));
create table passes (id uuid primary key default gen_random_uuid(), from_user uuid not null references profiles(id) on delete cascade, to_user uuid not null references profiles(id) on delete cascade, created_at timestamptz not null default now(), unique(from_user,to_user), check(from_user <> to_user));
create table matches (id uuid primary key default gen_random_uuid(), user_a uuid not null references profiles(id) on delete cascade, user_b uuid not null references profiles(id) on delete cascade, status text not null default 'active' check(status in ('active','unmatched')), created_at timestamptz not null default now(), unique(user_a,user_b), check(user_a < user_b));
create table messages (id uuid primary key default gen_random_uuid(), match_id uuid not null references matches(id) on delete cascade, sender_id uuid not null references profiles(id) on delete cascade, body text not null check(char_length(body) between 1 and 1000), created_at timestamptz not null default now(), read_at timestamptz);
create table blocks (id uuid primary key default gen_random_uuid(), blocker_id uuid not null references profiles(id) on delete cascade, blocked_id uuid not null references profiles(id) on delete cascade, created_at timestamptz not null default now(), unique(blocker_id,blocked_id), check(blocker_id <> blocked_id));
create table reports (id uuid primary key default gen_random_uuid(), reporter_id uuid not null references profiles(id) on delete cascade, reported_user_id uuid not null references profiles(id) on delete cascade, reason report_reason not null, description text check(char_length(description) <= 1000), status text not null default 'open' check(status in ('open','reviewing','actioned','dismissed')), reviewed_by uuid references profiles(id), reviewed_at timestamptz, created_at timestamptz not null default now());
create table admin_users (user_id uuid primary key references auth.users(id) on delete cascade); create table audit_log (id uuid primary key default gen_random_uuid(), admin_id uuid not null references auth.users(id), action text not null, target_id uuid, created_at timestamptz not null default now());
create index on likes(to_user); create index on matches(user_a); create index on matches(user_b); create index on messages(match_id,created_at); create index on reports(status); create index on blocks(blocked_id);
alter table profiles enable row level security; alter table likes enable row level security; alter table passes enable row level security; alter table matches enable row level security; alter table messages enable row level security; alter table blocks enable row level security; alter table reports enable row level security; alter table admin_users enable row level security; alter table audit_log enable row level security;
create policy "own profile" on profiles for all using (id=auth.uid()) with check (id=auth.uid()); create policy "safe discovery" on profiles for select using (onboarding_complete and not is_hidden and not is_suspended and not is_banned); create policy "own likes" on likes for all using (from_user=auth.uid()) with check(from_user=auth.uid()); create policy "own passes" on passes for all using (from_user=auth.uid()) with check(from_user=auth.uid()); create policy "match participant" on matches for select using (user_a=auth.uid() or user_b=auth.uid()); create policy "message participant" on messages for select using (exists(select 1 from matches m where m.id=match_id and (m.user_a=auth.uid() or m.user_b=auth.uid()) and m.status='active')); create policy "message sender" on messages for insert with check(sender_id=auth.uid()); create policy "own blocks" on blocks for all using(blocker_id=auth.uid()) with check(blocker_id=auth.uid()); create policy "own reports" on reports for insert with check(reporter_id=auth.uid()); create policy "admin only" on admin_users for select using(user_id=auth.uid());
create or replace function like_user(target uuid, kind like_kind default 'interested') returns jsonb language plpgsql security definer set search_path=public as $$ declare a uuid:=auth.uid(); low uuid; high uuid; match_id uuid; begin if a is null or a=target then raise exception 'invalid target'; end if; if exists(select 1 from blocks where (blocker_id=a and blocked_id=target) or (blocker_id=target and blocked_id=a)) then raise exception 'blocked'; end if; insert into likes(from_user,to_user,kind) values(a,target,kind) on conflict(from_user,to_user) do nothing; if exists(select 1 from likes where from_user=target and to_user=a) then low:=least(a,target); high:=greatest(a,target); insert into matches(user_a,user_b) values(low,high) on conflict(user_a,user_b) do update set status='active' returning id into match_id; return jsonb_build_object('matched',true,'match_id',match_id); end if; return jsonb_build_object('matched',false,'match_id',null); end $$;
